ee:message.ee:set-payload:
%dw 2.0
output application/json
var formattedPayload = (read(payload.analysis, "application/json"))
---
{
    "sessionId": payload.sessionId,
    "analysis": {
    "designRealatedQuestions": formattedPayload.DesignRealatedQuestions joinBy " | " default "NA",
    "configurationRelatedQuestions": formattedPayload.configurationRelatedQuestions joinBy " | "  default "NA",
    "securityRelatedQuestions": formattedPayload.securityRelatedQuestions joinBy " | "  default "NA",
    "deploymentRelatedQuestions": formattedPayload.deploymentRelatedQuestions joinBy " | "  default "NA",
    "otherGenericQuestions": formattedPayload.otherGenericQuestions joinBy " | "  default "NA"
}
}
